"""Central snapshot scheduling/cache tests using image files in a temporary directory."""
from pathlib import Path
import os,subprocess,tempfile
root=Path(__file__).resolve().parents[1];source=(root/'tests/test_backend.py').read_text();scope={'__file__':str(root/'tests/test_backend.py')}
exec(compile(source[:source.index('with tempfile.TemporaryDirectory()')],str(root/'tests/test_backend.py'),'exec'),scope)
main=r'''
static void request_image(struct Backend *b,struct AmiHASSMessage *m,const char *entity,int fresh){memset(m,0,sizeof(*m));m->magic=AMIHASS_MAGIC;m->abi=AMIHASS_ABI;m->msg.mn_Length=sizeof(*m);m->kind=AMIHASS_SNAPSHOT;strcpy(m->owner,"Camera.QA");strcpy(m->entity,entity);m->refresh=fresh;handle(b,m);}
int main(void){struct Backend *b=calloc(1,sizeof(*b));struct AmiHASSMessage m;struct AHCamera fixture;char version[20];FILE *f;int n;memset(&fixture,0,sizeof(fixture));sample_setting=1;reload(b);request_image(b,&m,"camera.amihass_sample_driveway",1);assert(m.result==AMIHASS_OK&&m.refresh==2048&&m.total==3908&&b->camera.data);strcpy(version,m.item.updated);request_image(b,&m,"camera.amihass_sample_driveway",1);assert(m.result==AMIHASS_OK&&!strcmp(version,m.item.updated));request_image(b,&m,"camera.real",1);assert(m.result==AMIHASS_UNCONFIGURED);now+=6;request_image(b,&m,"camera.amihass_sample_driveway",1);assert(m.result==AMIHASS_OK&&strcmp(version,m.item.updated));
 sample_setting=0;reload(b);b->network=b->network_known=1;b->next_network=now+60;connection_ok(b,now);request_image(b,&m,"camera.amihass_sample_driveway",1);assert(m.result==AMIHASS_UNCONFIGURED);request_image(b,&m,"camera.fixture",1);assert(m.result==AMIHASS_WAIT&&b->camera.pending);sent_phase=0;schedule(b,"fixture");assert(sent_phase==6&&strstr(sent_path,"/api/camera_proxy/camera.fixture?width=320&height=200"));assert(ah_camera_sample(&fixture));f=fopen("response","wb");assert(f&&fwrite(fixture.data,1,fixture.size,f)==fixture.size);fclose(f);strcpy(b->directory,".");b->last_http=200;complete(b,1);b->job=NULL;assert(b->camera.result==AMIHASS_OK&&!b->camera.pending&&b->camera.size==3908&&b->connected);request_image(b,&m,"camera.fixture",0);assert(m.result==AMIHASS_OK&&m.count==0);
 now+=6;request_image(b,&m,"camera.fixture",1);schedule(b,"fixture");b->last_http=503;complete(b,-1);b->job=NULL;assert(b->camera.result==AMIHASS_FAILED&&!b->camera.pending&&b->connected);now+=6;request_image(b,&m,"camera.fixture",1);schedule(b,"fixture");b->last_http=401;complete(b,-1);b->job=NULL;assert(b->auth_blocked&&!b->camera.pending&&!b->connected);
 sample_setting=1;reload(b);request_image(b,&m,"camera.amihass_sample_driveway",1);assert(b->camera.data);now+=31;schedule(b,"fixture");assert(!b->camera.data);{struct AmiHASSMessage t;sample_setting=0;reload(b);connection_ok(b,now);b->network=b->network_known=1;b->next_network=now+60;memset(&t,0,sizeof(t));t.msg.mn_ReplyPort=(struct MsgPort*)7;strcpy(t.owner,"Thumb.QA");strcpy(t.entity,"camera.size");strcpy(t.domain,"thumb");camera_request(b,&t,now);assert(b->camera.pending&&b->camera.small);
  /* a pending thumbnail is completed as a 96x60 image; the viewer then asks for full size */
  b->camera.pending=0;b->camera.result=AMIHASS_OK;memset(&t,0,sizeof(t));t.msg.mn_ReplyPort=(struct MsgPort*)8;strcpy(t.owner,"View.QA");strcpy(t.entity,"camera.size");camera_request(b,&t,now+6);assert(b->camera.pending&&!b->camera.small);
  b->camera.pending=0;b->camera.result=AMIHASS_OK;memset(&t,0,sizeof(t));t.msg.mn_ReplyPort=(struct MsgPort*)7;strcpy(t.owner,"Thumb.QA");strcpy(t.entity,"camera.size");strcpy(t.domain,"thumb");camera_request(b,&t,now+12);assert(!b->camera.pending&&!b->camera.small); /* full image serves tiles */
  camera_release(b,(struct MsgPort*)7,now+12);camera_release(b,(struct MsgPort*)8,now+12);ah_camera_clear(&b->camera);}
 {unsigned long cancelled;sample_setting=0;reload(b);connection_ok(b,now);b->network=b->network_known=1;b->next_network=now+60;b->low_memory=1;memset(&m,0,sizeof(m));m.msg.mn_ReplyPort=(struct MsgPort*)1;strcpy(m.owner,"Cancel.QA");strcpy(m.entity,"camera.fixture");m.refresh=1;camera_request(b,&m,now);assert(b->camera.pending&&camera_watchers(b,now)==1);cancelled=b->camera_cancels;camera_release(b,(struct MsgPort*)1,now);assert(!b->camera.pending&&!b->camera.data&&b->camera_cancels==cancelled+1);now+=6;camera_request(b,&m,now);b->phase=6;b->job=(struct MsgPort*)1;camera_release(b,(struct MsgPort*)1,now);assert(b->camera.discard&&b->camera.pending);camera_complete(b,1,now);assert(!b->camera.pending&&!b->camera.data&&!b->camera.discard);b->job=NULL;}ah_camera_clear(&fixture);ah_camera_clear(&b->camera);{if(b->subscriptions)FreeVec(b->subscriptions);free(b);}remove("response");puts("Camera broker: shared/throttled sample image, strict source isolation, bounded HTTP image completion, camera-only failure, auth latch and idle reclamation passed.");return 0;}
'''
with tempfile.TemporaryDirectory() as directory:
    p=Path(directory);(p/'exec').mkdir();(p/'exec/ports.h').write_text('#include <stdint.h>\ntypedef uint32_t ULONG;typedef int32_t LONG;struct MsgPort;struct Message {unsigned short mn_Length;struct MsgPort *mn_ReplyPort;};\n');(p/'test.c').write_text(scope['preamble']+scope['structs']+scope['stubs']+scope['functions']+main)
    cmd=[os.environ.get('CC','cc'),'-std=c99','-Wno-deprecated-declarations','-I'+str(p),'-I'+str(root/'SDK'),'-I'+str(root/'include'),str(p/'test.c')]+[str(root/'src'/name) for name in ('core.c','camera.c','sample.c','browser_data.c')]+['-o',str(p/'test')]
    if os.environ.get('SANITIZE')=='1':cmd+=['-fsanitize=address,undefined']
    subprocess.run(cmd,check=True);subprocess.run([str(p/'test')],cwd=p,check=True)
